/**
 * Format `value` (a Decimal) as `currency` for en_US.
 */
export function formatCurrency(value, currency) {
  const sign = isSigned(value) ? CURRENCY_PATTERN.minusSign : '';
  return sign + currency.symbol + formatMagnitude(value, currency.digits);
}
/**
 * Python's `float(str)` conversion, reimplemented for `argparse(type=float)`.
 *
 * CPython does this in two steps, and both matter:
 *
 *   1. `_PyUnicode_TransformDecimalAndSpaceToASCII` rewrites the string — ASCII is
 *      passed through untouched, non-ASCII whitespace collapses to a plain space,
 *      and any Unicode decimal digit folds to its ASCII equivalent (so `١٢٣` is a
 *      perfectly good `123`). Anything else non-ASCII poisons the string.
 *   2. `float_from_string_inner` strips *ASCII* whitespace and runs strtod.
 *
 * The split explains two behaviours a single trim would get wrong: U+00A0 is
 * accepted as padding (step 1 turns it into a space) while U+001C is rejected
 * (it is ASCII, so step 1 leaves it alone and step 2 does not consider it space).
 */

/** `Py_UNICODE_ISSPACE` restricted to the non-ASCII code points, used by step 1. */
function isUnicodeSpace(cp) {
  return (
    cp === 0x85 ||
    cp === 0xa0 ||
    cp === 0x1680 ||
    (cp >= 0x2000 && cp <= 0x200a) ||
    cp === 0x2028 ||
    cp === 0x2029 ||
    cp === 0x202f ||
    cp === 0x205f ||
    cp === 0x3000
