// digits[.digits] | .digits  — with an optional decimal exponent.
const DECIMAL_RE = /^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

/**
 * Parse `text` the way CPython's `float()` does.
 * Returns a JS number, or null when CPython would raise ValueError.
 */
export function pyFloat(text) {
  const ascii = transformDecimalAndSpaceToASCII(text);
  if (ascii === null) return null;

  const stripped = stripAsciiSpace(ascii);
  if (stripped === '') return null;

  let sign = 1;
  let body = stripped;
  if (body[0] === '+' || body[0] === '-') {
    if (body[0] === '-') sign = -1;
    body = body.slice(1);
  }
  if (body === '') return null;

  const lowered = body.toLowerCase();
  if (lowered === 'inf' || lowered === 'infinity') return sign * Infinity;
  if (lowered === 'nan') return sign * NaN;

  const cleaned = removeUnderscores(body);
  if (cleaned === null || !DECIMAL_RE.test(cleaned)) return null;

  // The regex has already excluded every form Number() would treat leniently
  // (empty string, hex, whitespace, "Infinity"), so this is a faithful strtod.
  return sign * Number(cleaned);
