/** Raised by `get_currency()` for a code the registry does not know. */
export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.name = 'CurrencyDoesNotExist';
    this.pyType = 'moneyed.classes.CurrencyDoesNotExist';
    this.code = code;
  }
